select x.source_id,x.pilot,x.default_unit from jsonb_to_recordset($pilot_seed$[{"source_id":"DB_001","pilot":{"sourceId":"DB_001","sourceVersion":"1.1.0","sourceCatalogVersion":"3.1.0-pilot.1","integrationVersion":"fe-program-pilot.1","usage":"STAGING_TEST","name":{"fr":"Squat gobelet avec haltère","en":"Dumbbell goblet squat"},"equipment":{"id":"dumbbell","labels":{"fr":"Haltères","en":"Dumbbells"}},"instructions":{"fr":{"setup":"Debout, tenez un haltère vertical contre le sternum avec les deux mains sous sa tête et les pieds stables.","execution":"Fléchissez ensemble les hanches et les genoux jusqu’à votre profondeur contrôlée, en gardant les talons au sol.","finish":"Poussez le sol pour revenir debout sans perdre le contrôle du tronc."},"en":{"setup":"Stand with stable feet and hold one dumbbell vertically at your breastbone, both hands under its upper head.","execution":"Bend your hips and knees together to your controlled depth while keeping your heels down.","finish":"Push through the floor to stand upright with your trunk controlled."}},"performance":{"measure":"repetitions","counting":{"fr":"Répétitions complètes","en":"Complete repetitions"},"load":{"fr":"Masse de l’unique haltère","en":"Mass of the single dumbbell"},"countingDecision":"PROPOSED","notes":{"fr":"Fiche générique utilisée pour ce test staging. Les modèles de machines proposés ne sont pas validés. Aucune résistance réelle ni charge totale n’est calculée automatiquement.","en":"Generic exercise used for this staging test. Proposed machine models are not approved. Actual resistance and total load are never calculated automatically."},"loadEntryBasis":"per_implement"}},"default_unit":"lb"},{"source_id":"DB_025","pilot":{"sourceId":"DB_025","sourceVersion":"1.2.0","sourceCatalogVersion":"3.1.0-pilot.1","integrationVersion":"fe-program-pilot.1","usage":"STAGING_TEST","name":{"fr":"Rowing unilatéral avec appui sur banc","en":"One-arm dumbbell row"},"equipment":{"id":"dumbbell","labels":{"fr":"Haltères","en":"Dumbbells"}},"instructions":{"fr":{"setup":"Placez la main et le genou opposés au bras de travail sur un banc fixe, le pied du côté actif au sol et l’haltère dans la main de travail.","execution":"Tirez le coude vers le flanc sans faire tourner le thorax ni avancer l’épaule.","finish":"Redescendez l’haltère jusqu’au bras long en gardant le bassin stable."},"en":{"setup":"Support your non-working hand and knee on a fixed bench, with your working-side foot on the floor and a dumbbell in your working hand.","execution":"Pull your elbow toward your side without rotating your chest or letting your shoulder roll forward.","finish":"Lower the dumbbell to a long arm while keeping your pelvis stable."}},"performance":{"measure":"repetitions","counting":{"fr":"Répétitions par bras","en":"Repetitions per arm"},"load":{"fr":"Masse de l’haltère du bras actif","en":"Mass of the working-arm dumbbell"},"countingDecision":"PROPOSED","notes":{"fr":"Fiche générique utilisée pour ce test staging. Les modèles de machines proposés ne sont pas validés. Aucune résistance réelle ni charge totale n’est calculée automatiquement.","en":"Generic exercise used for this staging test. Proposed machine models are not approved. Actual resistance and total load are never calculated automatically."},"loadEntryBasis":"per_implement"}},"default_unit":"lb"},{"source_id":"DB_034","pilot":{"sourceId":"DB_034","sourceVersion":"1.2.0","sourceCatalogVersion":"3.1.0-pilot.1","integrationVersion":"fe-program-pilot.1","usage":"STAGING_TEST","name":{"fr":"Curl alterné avec haltères","en":"Alternating dumbbell curl"},"equipment":{"id":"dumbbell","labels":{"fr":"Haltères","en":"Dumbbells"}},"instructions":{"fr":{"setup":"Debout, gardez un haltère de même charge dans chaque main, bras allongés et paumes vers l’avant.","execution":"Fléchissez le coude droit puis rabaissez l’haltère, en gardant l’épaule et le tronc stables.","finish":"Réalisez le même mouvement avec le bras gauche. Comptez les répétitions pour chaque bras séparément, sans regrouper droite et gauche en une répétition."},"en":{"setup":"Stand with equally loaded dumbbells in your hands, arms long and palms facing forward.","execution":"Curl the right dumbbell and lower it, keeping your shoulder and trunk still.","finish":"Repeat the movement with your left arm. Count repetitions for each arm separately; do not combine right and left into one repetition."}},"performance":{"measure":"repetitions","counting":{"fr":"Répétitions par bras","en":"Repetitions per arm"},"load":{"fr":"Masse par haltère, identique des deux côtés","en":"Mass per dumbbell, equal on both sides"},"countingDecision":"MAX_PER_ARM_2026_10_23","notes":{"fr":"Fiche générique utilisée pour ce test staging. Les modèles de machines proposés ne sont pas validés. Aucune résistance réelle ni charge totale n’est calculée automatiquement.","en":"Generic exercise used for this staging test. Proposed machine models are not approved. Actual resistance and total load are never calculated automatically."},"loadEntryBasis":"per_implement"}},"default_unit":"lb"},{"source_id":"DB_045","pilot":{"sourceId":"DB_045","sourceVersion":"1.1.0","sourceCatalogVersion":"3.1.0-pilot.1","integrationVersion":"fe-program-pilot.1","usage":"STAGING_TEST","name":{"fr":"Marche du fermier avec haltères","en":"Dumbbell farmer carry"},"equipment":{"id":"dumbbell","labels":{"fr":"Haltères","en":"Dumbbells"}},"instructions":{"fr":{"setup":"Debout dans un couloir dégagé, tenez deux haltères de même charge aux côtés, bras longs et prise neutre fermée.","execution":"Avancez à pas contrôlés en gardant le bassin et les épaules à niveau, sans balancer les haltères.","finish":"Arrêtez-vous avant de poser les deux haltères au sol de façon contrôlée."},"en":{"setup":"Stand in a clear lane holding equally loaded dumbbells at your sides, arms long and thumbs around the handles.","execution":"Walk forward with controlled steps, keeping your hips and shoulders level without swinging the dumbbells.","finish":"Stop before lowering both dumbbells to the floor under control."}},"performance":{"measure":"distance","counting":{"fr":"Distance totale parcourue pendant la série","en":"Total distance travelled during the set"},"load":{"fr":"Masse par haltère, identique des deux côtés","en":"Mass per dumbbell, equal on both sides"},"countingDecision":"PROPOSED","notes":{"fr":"Fiche générique utilisée pour ce test staging. Les modèles de machines proposés ne sont pas validés. Aucune résistance réelle ni charge totale n’est calculée automatiquement.","en":"Generic exercise used for this staging test. Proposed machine models are not approved. Actual resistance and total load are never calculated automatically."},"loadEntryBasis":"per_implement"}},"default_unit":"distance"},{"source_id":"BB_001","pilot":{"sourceId":"BB_001","sourceVersion":"1.1.0","sourceCatalogVersion":"3.1.0-pilot.1","integrationVersion":"fe-program-pilot.1","usage":"STAGING_TEST","name":{"fr":"Squat arrière barre haute","en":"High-bar back squat"},"equipment":{"id":"barbell","labels":{"fr":"Barres","en":"Barbell"}},"instructions":{"fr":{"setup":"Depuis un rack à sécurités, placez la barre sur la masse musculaire du haut des trapèzes avec une prise fermée et les pieds stables.","execution":"Fléchissez ensemble les hanches et les genoux jusqu’à votre profondeur contrôlée, en gardant les talons au sol.","finish":"Poussez le sol pour revenir debout et replacez la barre au rack après la série."},"en":{"setup":"From a rack with safety supports, position the bar on your upper trapezius muscles with a closed grip and stable feet.","execution":"Bend your hips and knees together to your controlled depth while keeping your heels down.","finish":"Push through the floor to stand upright and return the bar to the rack after the set."}},"performance":{"measure":"repetitions","counting":{"fr":"Répétitions complètes","en":"Complete repetitions"},"load":{"fr":"Charge totale réellement utilisée : barre + disques + colliers","en":"Actual total load: bar + plates + collars"},"countingDecision":"PROPOSED","notes":{"fr":"Fiche générique utilisée pour ce test staging. Les modèles de machines proposés ne sont pas validés. Aucune résistance réelle ni charge totale n’est calculée automatiquement.","en":"Generic exercise used for this staging test. Proposed machine models are not approved. Actual resistance and total load are never calculated automatically."},"loadEntryBasis":"total_external_mass"}},"default_unit":"lb"},{"source_id":"BB_012","pilot":{"sourceId":"BB_012","sourceVersion":"1.1.0","sourceCatalogVersion":"3.1.0-pilot.1","integrationVersion":"fe-program-pilot.1","usage":"STAGING_TEST","name":{"fr":"Soulevé de terre conventionnel","en":"Conventional barbell deadlift"},"equipment":{"id":"barbell","labels":{"fr":"Barres","en":"Barbell"}},"instructions":{"fr":{"setup":"Placez les pieds sous le bassin et saisissez la barre au sol en double pronation fermée, les mains à l’extérieur des jambes.","execution":"Poussez le sol en étendant les hanches et les genoux, bras longs et barre près des jambes, jusqu’à la station debout.","finish":"Reculez les hanches puis fléchissez les genoux pour reposer la barre au sol de façon contrôlée."},"en":{"setup":"Place your feet under your hips and take a closed double-overhand grip on the bar on the floor, with your hands outside your legs.","execution":"Push through the floor and extend your hips and knees to stand upright, keeping your arms long and the bar close to your legs.","finish":"Move your hips back, then bend your knees to return the bar to the floor under control."}},"performance":{"measure":"repetitions","counting":{"fr":"Répétitions complètes","en":"Complete repetitions"},"load":{"fr":"Charge totale réellement utilisée : barre + disques + colliers","en":"Actual total load: bar + plates + collars"},"countingDecision":"PROPOSED","notes":{"fr":"Fiche générique utilisée pour ce test staging. Les modèles de machines proposés ne sont pas validés. Aucune résistance réelle ni charge totale n’est calculée automatiquement.","en":"Generic exercise used for this staging test. Proposed machine models are not approved. Actual resistance and total load are never calculated automatically."},"loadEntryBasis":"total_external_mass"}},"default_unit":"lb"},{"source_id":"CA_001","pilot":{"sourceId":"CA_001","sourceVersion":"1.1.0","sourceCatalogVersion":"3.1.0-pilot.1","integrationVersion":"fe-program-pilot.1","usage":"STAGING_TEST","name":{"fr":"Développé poitrine debout à câbles","en":"Standing cable chest press"},"equipment":{"id":"cable","labels":{"fr":"Câbles","en":"Cables"}},"instructions":{"fr":{"setup":"Debout en fente, prenez les deux poignées D des poulies placées derrière vous à hauteur de poitrine, mains près du thorax.","execution":"Poussez les deux poignées devant la poitrine sans tourner le tronc ni casser les poignets.","finish":"Ramenez les mains près du thorax en contrôlant les câbles et en gardant les mêmes appuis."},"en":{"setup":"Stand in a split stance with both D-handles near your chest, using pulleys behind you at chest height.","execution":"Press both handles forward in front of your chest without rotating your trunk or bending your wrists.","finish":"Bring your hands back toward your chest under cable control while keeping the same foot position."}},"performance":{"measure":"repetitions","counting":{"fr":"Répétitions complètes","en":"Complete repetitions"},"load":{"fr":"Base de charge à confirmer sur l’appareil; ne pas déduire la résistance réelle","en":"Load basis must be confirmed on the machine; do not infer actual resistance"},"countingDecision":"PROPOSED","notes":{"fr":"Fiche générique utilisée pour ce test staging. Les modèles de machines proposés ne sont pas validés. Aucune résistance réelle ni charge totale n’est calculée automatiquement.","en":"Generic exercise used for this staging test. Proposed machine models are not approved. Actual resistance and total load are never calculated automatically."},"loadEntryBasis":"to_confirm"}},"default_unit":"configuration"},{"source_id":"CA_050","pilot":{"sourceId":"CA_050","sourceVersion":"1.1.0","sourceCatalogVersion":"3.1.0-pilot.1","integrationVersion":"fe-program-pilot.1","usage":"STAGING_TEST","name":{"fr":"Rowing unilatéral à demi-genou à câble","en":"Half-kneeling single-arm cable row"},"equipment":{"id":"cable","labels":{"fr":"Câbles","en":"Cables"}},"instructions":{"fr":{"setup":"Placez le genou du bras actif au sol et l’autre pied devant, face à une poulie au niveau du bas du thorax, poignée D dans la main active.","execution":"Tirez le coude vers les côtes sans tourner le thorax ni reculer le bassin.","finish":"Laissez le bras se rallonger sous contrôle en gardant le bassin et les appuis fixes."},"en":{"setup":"Kneel on your working-side knee with the opposite foot forward, facing a pulley at lower-chest height and holding a D-handle in your working hand.","execution":"Pull your elbow toward your ribs without rotating your chest or shifting your pelvis backward.","finish":"Let your arm lengthen under control while keeping your pelvis and support points still."}},"performance":{"measure":"repetitions","counting":{"fr":"Répétitions par bras","en":"Repetitions per arm"},"load":{"fr":"Réglage affiché sur la pile utilisée, avec son unité","en":"Displayed setting on the stack in use, with its unit"},"countingDecision":"PROPOSED","notes":{"fr":"Fiche générique utilisée pour ce test staging. Les modèles de machines proposés ne sont pas validés. Aucune résistance réelle ni charge totale n’est calculée automatiquement.","en":"Generic exercise used for this staging test. Proposed machine models are not approved. Actual resistance and total load are never calculated automatically."},"loadEntryBasis":"displayed_stack_setting"}},"default_unit":"lb"},{"source_id":"MA_018","pilot":{"sourceId":"MA_018","sourceVersion":"1.1.0","sourceCatalogVersion":"3.1.0-pilot.1","integrationVersion":"fe-program-pilot.1","usage":"STAGING_TEST","name":{"fr":"Développé poitrine à machine","en":"Machine chest press"},"equipment":{"id":"machine","labels":{"fr":"Machines","en":"Machine"}},"instructions":{"fr":{"setup":"Asseyez-vous le dos au dossier, placez les pieds sur les appuis prévus et réglez le siège et les poignées selon le modèle.","execution":"Poussez les deux poignées suivant le trajet de la machine, en gardant le dos en contact avec le dossier et les poignets alignés.","finish":"Ramenez les poignées sous contrôle jusqu’au départ toléré par les épaules, sans laisser retomber les leviers."},"en":{"setup":"Sit with your back against the pad, place your feet on the intended supports and adjust the seat and handles for the selected model.","execution":"Press both handles along the machine’s path, keeping your back against the pad and your wrists aligned.","finish":"Return the handles under control to the starting position your shoulders can tolerate, without letting the levers drop."}},"performance":{"measure":"repetitions","counting":{"fr":"Répétitions complètes","en":"Complete repetitions"},"load":{"fr":"Base de charge à confirmer sur l’appareil; ne pas déduire la résistance réelle","en":"Load basis must be confirmed on the machine; do not infer actual resistance"},"countingDecision":"PROPOSED","notes":{"fr":"Fiche générique utilisée pour ce test staging. Les modèles de machines proposés ne sont pas validés. Aucune résistance réelle ni charge totale n’est calculée automatiquement.","en":"Generic exercise used for this staging test. Proposed machine models are not approved. Actual resistance and total load are never calculated automatically."},"loadEntryBasis":"to_confirm"}},"default_unit":"configuration"},{"source_id":"MA_028","pilot":{"sourceId":"MA_028","sourceVersion":"1.1.0","sourceCatalogVersion":"3.1.0-pilot.1","integrationVersion":"fe-program-pilot.1","usage":"STAGING_TEST","name":{"fr":"Traction assistée à machine","en":"Assisted pull-up machine"},"equipment":{"id":"machine","labels":{"fr":"Machines","en":"Machine"}},"instructions":{"fr":{"setup":"Réglez l’assistance puis, selon la procédure de la machine, saisissez les poignées hautes en pronation et placez les genoux sur le coussin mobile prévu.","execution":"Tirez le corps vers les poignées sans balancer le tronc, en gardant les genoux en contact avec le coussin qui accompagne la montée.","finish":"Redescendez sous contrôle jusqu’à l’allongement des bras que vous maîtrisez, puis quittez le coussin selon la procédure de la machine."},"en":{"setup":"Set the assistance, then follow the machine’s access procedure to grasp the upper handles with an overhand grip and place your knees on the moving pad.","execution":"Pull your body toward the handles without swinging, keeping your knees on the pad as it rises with you.","finish":"Lower under control to the arm extension you can maintain, then leave the pad using the machine’s exit procedure."}},"performance":{"measure":"repetitions","counting":{"fr":"Répétitions complètes","en":"Complete repetitions"},"load":{"fr":"Base de charge à confirmer sur l’appareil; ne pas déduire la résistance réelle","en":"Load basis must be confirmed on the machine; do not infer actual resistance"},"countingDecision":"PROPOSED","notes":{"fr":"Fiche générique utilisée pour ce test staging. Les modèles de machines proposés ne sont pas validés. Aucune résistance réelle ni charge totale n’est calculée automatiquement.","en":"Generic exercise used for this staging test. Proposed machine models are not approved. Actual resistance and total load are never calculated automatically."},"loadEntryBasis":"to_confirm"}},"default_unit":"configuration"},{"source_id":"MA_063","pilot":{"sourceId":"MA_063","sourceVersion":"1.1.0","sourceCatalogVersion":"3.1.0-pilot.1","integrationVersion":"fe-program-pilot.1","usage":"STAGING_TEST","name":{"fr":"Rowing unilatéral à machine avec appui de poitrine","en":"Single-arm chest-supported machine row"},"equipment":{"id":"machine","labels":{"fr":"Machines","en":"Machine"}},"instructions":{"fr":{"setup":"Réglez le siège et l’appui thoracique, posez les pieds sur les appuis et prenez la poignée du bras actif, l’autre main sur le support fixe prévu.","execution":"Tirez la poignée vers le flanc en reculant le coude près des côtes, sans tourner le bassin ni décoller la poitrine.","finish":"Rallongez le bras sous contrôle jusqu’au départ, sans hausser l’épaule ni déplacer le levier inactif."},"en":{"setup":"Adjust the seat and chest pad, place your feet on the supports and grasp the working handle, keeping your other hand on the intended fixed support.","execution":"Pull the handle toward your side with the elbow close to your ribs, without rotating your pelvis or lifting your chest from the pad.","finish":"Extend the arm under control to the start, without shrugging or moving the inactive lever."}},"performance":{"measure":"repetitions","counting":{"fr":"Répétitions par bras","en":"Repetitions per arm"},"load":{"fr":"Base de charge à confirmer sur l’appareil; ne pas déduire la résistance réelle","en":"Load basis must be confirmed on the machine; do not infer actual resistance"},"countingDecision":"PROPOSED","notes":{"fr":"Fiche générique utilisée pour ce test staging. Les modèles de machines proposés ne sont pas validés. Aucune résistance réelle ni charge totale n’est calculée automatiquement.","en":"Generic exercise used for this staging test. Proposed machine models are not approved. Actual resistance and total load are never calculated automatically."},"loadEntryBasis":"to_confirm"}},"default_unit":"configuration"},{"source_id":"BW_021","pilot":{"sourceId":"BW_021","sourceVersion":"1.1.0","sourceCatalogVersion":"3.1.0-pilot.1","integrationVersion":"fe-program-pilot.1","usage":"STAGING_TEST","name":{"fr":"Pompe au sol","en":"Push-up"},"equipment":{"id":"bodyweight","labels":{"fr":"Poids du corps","en":"Bodyweight"}},"instructions":{"fr":{"setup":"Posez les mains près de la largeur des épaules et alignez tête, bassin et jambes sur les pointes de pieds.","execution":"Fléchissez les coudes pour abaisser le thorax en gardant le corps en ligne.","finish":"Repoussez le sol pour retrouver les bras allongés sans laisser le bassin s’affaisser."},"en":{"setup":"Place your hands near shoulder width and align your head, hips and legs while supported on your toes.","execution":"Bend your elbows to lower your chest while keeping your body aligned.","finish":"Push the floor away to straighten your arms without letting your hips sag."}},"performance":{"measure":"repetitions","counting":{"fr":"Répétitions complètes","en":"Complete repetitions"},"load":{"fr":"Poids du corps : aucune charge externe pour cette variante","en":"Bodyweight: no external load for this variation"},"countingDecision":"PROPOSED","notes":{"fr":"Fiche générique utilisée pour ce test staging. Les modèles de machines proposés ne sont pas validés. Aucune résistance réelle ni charge totale n’est calculée automatiquement.","en":"Generic exercise used for this staging test. Proposed machine models are not approved. Actual resistance and total load are never calculated automatically."},"loadEntryBasis":"not_applicable"}},"default_unit":"lb"},{"source_id":"BW_049","pilot":{"sourceId":"BW_049","sourceVersion":"1.1.0","sourceCatalogVersion":"3.1.0-pilot.1","integrationVersion":"fe-program-pilot.1","usage":"STAGING_TEST","name":{"fr":"Planche sur avant-bras","en":"Forearm plank"},"equipment":{"id":"bodyweight","labels":{"fr":"Poids du corps","en":"Bodyweight"}},"instructions":{"fr":{"setup":"Posez les avant-bras au sol, coudes sous les épaules, avec les genoux encore en appui.","execution":"Décollez les genoux et maintenez tête, bassin et chevilles alignés en respirant.","finish":"Reposez les genoux avant de relâcher le tronc."},"en":{"setup":"Place your forearms on the floor with your elbows under your shoulders and your knees supported.","execution":"Lift your knees and hold your head, hips and ankles aligned while breathing.","finish":"Lower your knees before relaxing your trunk."}},"performance":{"measure":"duration","counting":{"fr":"Secondes de maintien, sans compter l’installation","en":"Hold duration in seconds, excluding setup"},"load":{"fr":"Poids du corps : aucune charge externe pour cette variante","en":"Bodyweight: no external load for this variation"},"countingDecision":"PROPOSED","notes":{"fr":"Fiche générique utilisée pour ce test staging. Les modèles de machines proposés ne sont pas validés. Aucune résistance réelle ni charge totale n’est calculée automatiquement.","en":"Generic exercise used for this staging test. Proposed machine models are not approved. Actual resistance and total load are never calculated automatically."},"loadEntryBasis":"not_applicable"}},"default_unit":"sec"},{"source_id":"KB_015","pilot":{"sourceId":"KB_015","sourceVersion":"1.1.0","sourceCatalogVersion":"3.1.0-pilot.1","integrationVersion":"fe-program-pilot.1","usage":"STAGING_TEST","name":{"fr":"Swing à deux mains à hauteur de poitrine","en":"Two-Hand Kettlebell Swing"},"equipment":{"id":"kettlebell","labels":{"fr":"Kettlebells","en":"Kettlebell"}},"instructions":{"fr":{"setup":"Tenez une kettlebell à deux mains, pieds environ largeur épaules, puis reculez les hanches avec la cloche entre les cuisses.","execution":"Étendez vivement les hanches pour faire flotter la cloche devant la poitrine, bras longs.","finish":"Guidez son retour entre les cuisses en reculant les hanches, sans tirer avec les épaules."},"en":{"setup":"Hold one kettlebell with both hands, feet about shoulder width, then hinge with the bell between your thighs.","execution":"Extend your hips briskly to let the bell float in front of your chest with long arms.","finish":"Guide it back between your thighs by hinging, without lifting it with your shoulders."}},"performance":{"measure":"repetitions","counting":{"fr":"Répétitions complètes","en":"Complete repetitions"},"load":{"fr":"Masse de la kettlebell unique","en":"Mass of the single kettlebell"},"countingDecision":"PROPOSED","notes":{"fr":"Fiche générique utilisée pour ce test staging. Les modèles de machines proposés ne sont pas validés. Aucune résistance réelle ni charge totale n’est calculée automatiquement.","en":"Generic exercise used for this staging test. Proposed machine models are not approved. Actual resistance and total load are never calculated automatically."},"loadEntryBasis":"per_implement"}},"default_unit":"lb"},{"source_id":"BA_027","pilot":{"sourceId":"BA_027","sourceVersion":"1.1.0","sourceCatalogVersion":"3.1.0-pilot.1","integrationVersion":"fe-program-pilot.1","usage":"STAGING_TEST","name":{"fr":"Pallof press debout avec bande","en":"Standing Band Pallof Press"},"equipment":{"id":"band","labels":{"fr":"Élastiques","en":"Resistance band"}},"instructions":{"fr":{"setup":"Placez l’ancrage à gauche à hauteur du sternum et tenez la poignée à deux mains devant la poitrine, pieds parallèles stables.","execution":"Tendez les bras devant vous sans laisser les épaules ou le bassin tourner vers l’ancrage.","finish":"Ramenez les mains au sternum en gardant le tronc face devant."},"en":{"setup":"Set the anchor to your left at sternum height and hold the handle with both hands at your chest, feet stable and parallel.","execution":"Extend your arms in front without letting your shoulders or hips turn toward the anchor.","finish":"Bring your hands back to your sternum while keeping your trunk facing forward."}},"performance":{"measure":"repetitions","counting":{"fr":"Répétitions par côté d’ancrage","en":"Repetitions per anchor side"},"load":{"fr":"Identifier la bande et son montage; aucune charge en livres ou kilos n’est déduite","en":"Identify the band and setup; no load in pounds or kilograms is inferred"},"countingDecision":"PROPOSED","notes":{"fr":"Fiche générique utilisée pour ce test staging. Les modèles de machines proposés ne sont pas validés. Aucune résistance réelle ni charge totale n’est calculée automatiquement.","en":"